import{_ as t,o as a,c as i,al as r}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"DIY Builds (Multicopter)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/frames_multicopter/diy_builds.md","filePath":"zh/frames_multicopter/diy_builds.md"}'),o={name:"zh/frames_multicopter/diy_builds.md"};function l(s,e,d,n,u,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="diy-builds-multicopter" tabindex="-1">DIY Builds (Multicopter) <a class="header-anchor" href="#diy-builds-multicopter" aria-label="Permalink to &quot;DIY Builds (Multicopter)&quot;">​</a></h1><p>Do-it-yourself (DIY) builds describe how to assemble a vehicle from parts that are sourced separately.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="./../frames_multicopter/kits">Kits</a> provide a gentler introduction to building a drone, and should be considered if you are just starting out!</p><p>Note that some parts used in the builds linked below may no longer be available. Consider it part of the challenge to find adequate replacement parts!</p></div><p>At the easier end of the scale of DIY builds are those that take an existing RC vehicle and graft on a flight controller. At the harder end of the scale are &quot;unique&quot; vehicles where some parts may be fabricated using a 3D printer. Somewhere in the middle are builds that use separate but readily available components: frame, motors, ESC, propellers, flight controller, and so on.</p><p>DIY Builds:</p><ul><li><a href="./../frames_multicopter/omnicopter">Omnicopter (KakuteH7)</a></li><li><a href="./../frames_multicopter/dji_f450_cuav_5plus">DJI F450 (CUAV v5+)</a></li><li><a href="./../frames_multicopter/dji_f450_cuav_5nano">DJI F450 (CUAV v5 nano)</a></li></ul>',6)])])}const _=t(o,[["render",l]]);export{m as __pageData,_ as default};
